from flask import Flask, Blueprint, request, jsonify

users_bp = Blueprint('users', __name__)

@users_bp.route('/')
def list_users():
    return jsonify({'users': ['alice', 'bob', 'charlie']}), 200

@users_bp.route('/<int:user_id>')
def get_user(user_id):
    users = {1: 'alice', 2: 'bob', 3: 'charlie'}
    user = users.get(user_id)
    if user:
        return jsonify({'id': user_id, 'name': user}), 200
    return jsonify({'error': 'User not found'}), 404

@users_bp.route('/', methods=['POST'])
def create_user():
    data = request.get_json()
    return jsonify({'message': 'User created', 'data': data}), 201

@users_bp.route('/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    data = request.get_json()
    return jsonify({'message': 'User updated', 'id': user_id, 'data': data}), 200

@users_bp.route('/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    return jsonify({'message': 'User deleted', 'id': user_id}), 200

app = Flask(__name__)

@app.route('/')
def home():
    return jsonify({'message': 'Welcome to Flask API'}), 200

app.register_blueprint(users_bp, url_prefix='/users')

if __name__ == '__main__':
    app.run(debug=True, host='127.0.0.1', port=5000)

